/* eslint-disable @typescript-eslint/no-explicit-any */
import { noop } from '@game-studio/utilities';
import { MessageChannelFactory, BaseMessageChannel } from '../message-channels';
import { OperatorProxy, ChatProxy, SubGameProxy } from '../proxies';
import { AuthTimeout, SessionTimeout } from '../utilis';
import { IChatParentEvents, GetMessageEvent, IGameChildEvents, IOperatorParentEvents, IAuthenticatePayload, IGameConnectionOptions, ISubGameProxyEvents, GetUnionizedMessageEvent, IRequestSubGameUrlPayload } from '../types';

export class GameConnection {
    public operator: OperatorProxy;
    private chatProxy: ChatProxy | null;
    private subGameProxy: SubGameProxy | null;
    public subGameIFrame: HTMLIFrameElement | null;
    private operatorHandlers: IGameChildEvents;
    private chatHandlers: IChatParentEvents;
    private subGameProxyHandlers: ISubGameProxyEvents;
    private messageChannel: BaseMessageChannel<IOperatorParentEvents, IOperatorParentEvents>;

    constructor(options: IGameConnectionOptions) {
        this.operator = new OperatorProxy(options);
        this.chatProxy = null;
        this.subGameProxy = null;
        this.subGameIFrame = null;

        const originalAuthenticateHandler = options.operatorHandlers.authenticate;

        this.operatorHandlers = {
            ...options.operatorHandlers,
            authenticate: (payload) => {
                AuthTimeout.cancel();
                originalAuthenticateHandler(payload);
            }
        };

        this.chatHandlers = {
            ...options.chatHandlers,
            onInit: noop,
            onLoaded: noop
        };

        this.subGameProxyHandlers = options.subGameProxyHandlers;

        if (options.type === 'web') {
            this.messageChannel = MessageChannelFactory.create({
                source: 'game',
                type: 'web',
                target: window,
                onMessageCallback: (event) => this.onMessage(event)
            });
        } else {
            this.messageChannel = MessageChannelFactory.create({
                source: 'game',
                type: 'native',
                platform: options.platform,
                handlers: this.operatorHandlers,
                chatHandlers: this.chatHandlers
            });
        }
    }

    public get chat() {
        if (!this.chatProxy) {
            throw new Error('No chat proxy has been created');
        }

        return this.chatProxy;
    }

    public get subGame() {
        return this.subGameProxy;
    }

    public createSubGame(subGameIFrame: HTMLIFrameElement, url: string, payload: IAuthenticatePayload) {
        this.subGameIFrame = subGameIFrame;
        this.subGameProxy = new SubGameProxy(subGameIFrame, (event) => this.onProxyMessage(event));
        // We setup the waitFor promise before loading the page in the iframe. To be sure we don't miss the onInit request
        const authPromise = this.subGameProxy.authenticate(payload);
        subGameIFrame.src = url;
        return authPromise;
    }

    public closeSubGame(): void {
        if (this.subGameProxy) {
            this.subGameProxy.disconnect();
            this.subGameProxy = null;
        }

        if (this.subGameIFrame) {
            this.subGameIFrame.src = '';
        }
    }

    public async createChat(chatIFrame: HTMLIFrameElement, url: string) {
        this.chatProxy = new ChatProxy(chatIFrame);
        chatIFrame.src = url;
    }

    public async onRequestSubGameUrl(payload: IRequestSubGameUrlPayload) {
        this.messageChannel.send('onRequestSubGameUrl', payload);
        return await this.messageChannel.waitForResponse('openSubGameUrl', 'operator');
    }

    private onMessage(event: GetMessageEvent<IOperatorParentEvents, keyof IOperatorParentEvents>) {
        if (!event.data.type || !Object.keys(event.data).includes('payload')) {
            return;
        }

        switch (event.data.source) {
            case 'chat':
                this.onChatMessage(event as any);
                break;
            case 'operator':
                this.onOperatorMessage(event as any);
                break;
        }
    }

    private onProxyMessage(event: GetMessageEvent<IOperatorParentEvents, keyof IOperatorParentEvents>) {
        const excluded = ['onInit', 'onLoaded', 'onAuthenticated', 'onSessionInfo', 'onSessionTimeout', 'onStyleUpdate', 'onGameRedirect', 'onCloseGame', 'onSettingsClosed'];

        if (!excluded.includes(event.data.type)) {
            this.messageChannel.send(event.data.type, event.data.payload);
        }

        if (this.subGameProxyHandlers[event.data.type as keyof ISubGameProxyEvents]) {
            this.subGameProxyHandlers[event.data.type as keyof ISubGameProxyEvents](event.data.payload as any);
        }
    }

    private onChatMessage(event: GetMessageEvent<IChatParentEvents, keyof IChatParentEvents>) {
        if (!this.chatHandlers[event.data.type]) {
            console.warn(`Could not find chat handler "${event.data.type}"`);
            return;
        }

        this.chatHandlers[event.data.type](event.data.payload as any);
    }

    private onOperatorMessage(event: GetUnionizedMessageEvent<IGameChildEvents, keyof IGameChildEvents>) {
        if (!this.operatorHandlers[event.data.type]) {
            console.warn(`Could not find operator handler "${event.data.type}"`);
            return;
        }

        this.operatorHandlers[event.data.type](event.data.payload as any);

        if (event.data.type === 'authenticate' && event.data.payload.sessionTimeoutMs) {
            SessionTimeout.start(event.data.payload.sessionTimeoutMs, () => this.operator.onSessionTimeout());
        }
    }
}
